import sys
import json

def evaluate_acl(acl_rules, request):
    """
    Evaluate the ACL rules against the request.
    Returns True if the request is allowed, False otherwise.
    """
    for rule in acl_rules:
        if all(rule.get(key) == request.get(key) for key in rule if key != 'allow'):
            return rule.get('allow', False)
    return False

def main():
    try:
        # Read input from stdin
        input_data = sys.stdin.read().strip()
        if not input_data:
            print(json.dumps({"error": "No input provided"}), flush=True)
            return

        # Parse input JSON
        data = json.loads(input_data)
        acl_rules = data.get('acl_rules', [])
        request = data.get('request', {})

        # Validate input structure
        if not isinstance(acl_rules, list) or not isinstance(request, dict):
            print(json.dumps({"error": "Invalid input format"}), flush=True)
            return

        # Evaluate ACL
        result = evaluate_acl(acl_rules, request)

        # Output result as JSON
        print(json.dumps({"allowed": result}), flush=True)

    except json.JSONDecodeError:
        print(json.dumps({"error": "Invalid JSON input"}), flush=True)
    except Exception as e:
        print(json.dumps({"error": str(e)}), flush=True)

if __name__ == "__main__":
